t.script:
(function () {
    const video = document.getElementById('barcodeVideo');
    const input = document.getElementById('barcodeInput');
    const resultBox = document.getElementById('barcodeResult');
    const startBtn = document.getElementById('startCameraBtn');
    const stopBtn = document.getElementById('stopCameraBtn');
    const lookupBtn = document.getElementById('lookupBarcodeBtn');
    let stream = null;
    let timer = null;

    function playBeep(ok) {
        try {
            const Ctx = window.AudioContext || window.webkitAudioContext;
            const ctx = new Ctx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = ok ? 'sine' : 'sawtooth';
            osc.frequency.value = ok ? 920 : 280;
            gain.gain.value = 0.12;
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start();
            osc.stop(ctx.currentTime + 0.14);
        } catch (e) {}
    }

    async function lookupCode(code) {
        const clean = (code || '').trim();
        if (!clean) return;
        const resp = await fetch('/barcode/lookup', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {code: clean}, id: Date.now()}),
        });
        const data = await resp.json();
        const res = data.result || {};
        playBeep(Boolean(res.found));
        resultBox.classList.remove('d-none', 'alert-success', 'alert-warning');
        resultBox.classList.add(res.found ? 'alert-success' : 'alert-warning');
        if (res.kind === 'product') {
            resultBox.innerHTML = 'Product: ' + res.name + ' | SKU: ' + res.sku + ' | On Hand: ' + res.qty_available;
        } else if (res.kind === 'picking') {
            resultBox.innerHTML = 'Transfer: ' + res.name + ' (' + res.state + ') | Partner: ' + res.partner;
        } else {
            resultBox.textContent = res.message || 'Not found';
        }
    }

    lookupBtn.addEventListener('click', () => lookupCode(input.value));
    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); lookupCode(input.value); } });

    stopBtn.addEventListener('click', () => {
        if (timer) clearInterval(timer);
        if (stream) { stream.getTracks().forEach(t => t.stop()); stream = null; }
        video.style.display = 'none';
    });

    startBtn.addEventListener('click', async () => {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            resultBox.classList.remove('d-none', 'alert-success');
            resultBox.classList.add('alert-warning');
            resultBox.textContent = 'Camera unavailable in this browser context; use USB scanner or manual input above.';
            return;
        }
        stream = await navigator.mediaDevices.getUserMedia({video: {facingMode: 'environment'}});
        video.srcObject = stream;
        video.style.display = 'block';
        if ('BarcodeDetector' in window) {
            const detector = new window.BarcodeDetector();
            timer = setInterval(async () => {
                try {
                    const codes = await detector.detect(video);
                    if (codes && codes.length) {
                        input.value = codes[0].rawValue;
                        await lookupCode(codes[0].rawValue);
                    }
                } catch (e) {}
            }, 750);
        }
    });
})();
